        options: [
          { id: 'q1_a', label: 'Python' },
          { id: 'q1_b', label: 'C++' },
          { id: 'q1_c', label: 'JavaScript' },
          { id: 'q1_d', label: 'Java' }
        ]
      },
      {
        id: 'q2',
        question: 'Which languages are known for strong type systems?',
        options: [
          { id: 'q2_a', label: 'TypeScript' },
          { id: 'q2_b', label: 'Rust' },
          { id: 'q2_c', label: 'Lua' },
          { id: 'q2_d', label: 'Go' }
        ]
      },
      {
        id: 'q3',
        question: 'Which of these languages run on the Java Virtual Machine (JVM)?',
        options: [
          { id: 'q3_a', label: 'Kotlin' },
          { id: 'q3_b', label: 'Scala' },
          { id: 'q3_c', label: 'Ruby' },
          { id: 'q3_d', label: 'Clojure' }
        ]
      }
    ];
    this.init();
  }

  init() {
    this.renderQuiz();
    this.attachEventListeners();
  }

  renderQuiz() {
    const quizForm = document.getElementById('quiz-form');
    quizForm.innerHTML = '';

    this.questions.forEach((question, index) => {
      const formField = this.createFormField(question, index);
      quizForm.appendChild(formField);
    });

    const submitButton = this.createSubmitButton();
    quizForm.appendChild(submitButton);
  }

  createFormField(question, index) {
    const formField = document.createElement('div');
    formField.className = 'form-field';

    const questionLabel = document.createElement('label');
    questionLabel.className = 'question-label';
    questionLabel.setAttribute('id', `${question.id}-label`);
    questionLabel.textContent = `${index + 1}. ${question.question}`;
    formField.appendChild(questionLabel);

    if (question.helpText) {
      const helpText = document.createElement('div');
      helpText.className = 'help-text';
      helpText.textContent = question.helpText;
      formField.appendChild(helpText);
    }

    const checkboxGroup = document.createElement('div');
    checkboxGroup.className = 'checkbox-group';
    checkboxGroup.setAttribute('role', 'group');
    checkboxGroup.setAttribute('aria-labelledby', `${question.id}-label`);

    question.options.forEach((option) => {
      const wrapper = document.createElement('div');
      wrapper.className = 'checkbox-wrapper';

      const checkbox = document.createElement('input');
      checkbox.type = 'checkbox';
      checkbox.id = option.id;
      checkbox.name = question.id;
      checkbox.value = option.id;
      checkbox.setAttribute('data-question', question.id);

      const label = document.createElement('label');
      label.setAttribute('for', option.id);
      label.textContent = option.label;

      wrapper.appendChild(checkbox);
      wrapper.appendChild(label);
      checkboxGroup.appendChild(wrapper);
    });

    formField.appendChild(checkboxGroup);
    return formField;
  }

  createSubmitButton() {
    const button = document.createElement('button');
    button.type = 'submit';
    button.className = 'submit-button';
    button.textContent = 'Submit Quiz';
    button.setAttribute('id', 'submit-button');
    return button;
  }

  attachEventListeners() {
    const form = document.getElementById('quiz-form');
    form.addEventListener('submit', (e) => this.handleSubmit(e));
  }

  handleSubmit(e) {
    e.preventDefault();

    const answers = {};
    this.questions.forEach((question) => {
      const selected = document.querySelectorAll(
        `input[data-question="${question.id}"]:checked`
      );
      answers[question.id] = Array.from(selected).map((input) => input.value);
    });

    console.log('Quiz Answers:', answers);
    alert('Thank you for completing the quiz! Check the console for your answers.');
  }
}

document.addEventListener('DOMContentLoaded', () => {
  new QuizApp();
});
